// Normalizacion y validacion inicial de la solicitud del comensal
const body = $input.first().json.body || $input.first().json;
const mensaje = body.mensaje || body.prompt || body.text || '';

if (!mensaje || mensaje.trim().length === 0) {
  return [{
    json: {
      valido: false,
      error: 'El campo "mensaje" es obligatorio y no puede estar vacio.',
      mensaje: ''
    }
  }];
}

// Fecha actual de referencia para interpretar fechas relativas (ej. manana, este viernes)
const now = new Date();
const hoyISO = now.toISOString().split('T')[0];

return [{
  json: {
    valido: true,
    mensaje: mensaje.trim(),
    fecha_referencia: hoyISO,
    zona_horaria: 'America/Costa_Rica'
  }
}];

// Formatear la salida final hacia el Contrato Superior JSON: { ok, data, error }
const item = $input.first().json;

// Si hubo error de validacion inicial previa al agente
if (item.valido === false) {
  return [{
    json: {
      ok: false,
      data: null,
      error: item.error
    }
  }];
}

// Extraer la respuesta generada por el AI Agent
const outputText = item.output || item.text || (typeof item === 'string' ? item : JSON.stringify(item));

return [{
  json: {
    ok: true,
    data: {
      mensaje: outputText,
      agente: 'Restaurante AI Agent Caso 2',
      timestamp: new Date().toISOString()
    },
    error: null
  }
}];
